#include <iostream>
#include <vector>
#include <cstdlib>

int partition(std::vector<int>& arr, int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            int tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }
    }
    int tmp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = tmp;
    return i + 1;
}

void quick_sort_recursive(std::vector<int>& arr, int low, int high) {
    if (low >= high) return;
    int pivot = partition(arr, low, high);
    quick_sort_recursive(arr, low, pivot - 1);
    quick_sort_recursive(arr, pivot + 1, high);
}

void quick_sort(std::vector<int>& arr) {
    if (arr.size() <= 1) return;
    quick_sort_recursive(arr, 0, arr.size() - 1);
}
